diff --git a/.github/workflows/ai-teammate.yml b/.github/workflows/ai-teammate.yml
index 9f83a330a..9fad52c05 100644
--- a/.github/workflows/ai-teammate.yml
+++ b/.github/workflows/ai-teammate.yml
@@ -167,14 +167,12 @@ jobs:
     # per-SHA concurrency awf#14) go live on merge, no re-pin ceremony.
     # Accepted trade-off: a mutable ref executes whatever sits at the awf
     # main head at run start. The ENGINE (dmtools-agents) stays pinned
-    # separately via factory_ref below. Flip in lockstep with the other
     # machine-loop stubs — guarded by
     # test/machine_kit/factory_stub_ref_test.dart.
     uses: IstiN/dmtools-agentic-workflows/.github/workflows/factory-teammate.yml@main
     with:
       # The literal uses-ref: the factory requires it (it cannot derive its
       # own ref — github.workflow_ref in a called workflow is the CALLER's).
-      factory_ref: ${{ vars.AGENTS_FACTORY_REF || 'aa5ddd8bd78e64c9ce77a43b31bc63b40b0f8d7a' }}
       flutter-version: 'stable'  # explicit: awf no longer defaults to a Flutter toolchain
       # STRING — number/choice-typed reusable inputs cannot take expressions.
       issue: ${{ needs.gate.outputs.issue || github.event.inputs.issue }}
diff --git a/test/machine_kit/factory_stub_ref_test.dart b/test/machine_kit/factory_stub_ref_test.dart
index 043f9409b..3538a0f96 100644
--- a/test/machine_kit/factory_stub_ref_test.dart
+++ b/test/machine_kit/factory_stub_ref_test.dart
@@ -109,18 +109,15 @@ void main() {
     }
   });

-  test('engine pin: ai-teammate passes a 40-hex factory_ref; sm/merge '
-      'carry none (AW resolves the engine from releases)', () {
-    final engineRef = RegExp(r"factory_ref:\s*\$\{\{\s*vars\.AGENTS_FACTORY_REF\s*\|\|\s*'([0-9a-f]{40})'\s*\}\}")
-        .firstMatch(teammate);
-    expect(
-      engineRef,
-      isNotNull,
-      reason:
-          'ai-teammate must pass factory_ref — the factory declares it '
-          'required and cannot derive its own engine commit',
-    );
+  test('engine pin: NO wrapper passes factory_ref (AW resolves the engine '
+      'from releases; the input is gone from the factory contract)', () {
+    // Absence-contract since fa#1657 (2026-10-16): the fa wrapper stopped
+    // passing factory_ref — the factory resolves the engine from
+    // dmtools-agents releases via vars (latest default), same as sm/merge.
+    // The historical 40-hex pin died with the factory_ref input removal
+    // (awf#41/#42); the optional no-op (awf#44) is transitional only.
     for (final entry in {
+      'ai-teammate.yml': teammate,
       'machine-sm.yml': sm,
       'machine-merge.yml': merge,
     }.entries) {
@@ -128,9 +125,9 @@ void main() {
         entry.value.contains('factory_ref:'),
         isFalse,
         reason:
-            '${entry.key}: AW factory-sm/merge have no factory_ref '
-            'input — the engine resolves from dmtools-agents releases '
-            'via vars (latest default)',
+            '${entry.key}: must not pass factory_ref — the engine '
+            'resolves from dmtools-agents releases via vars '
+            '(latest default)',
       );
     }
   });

{
  "key": "pr-1657",
  "fields": {
    "summary": "hotfix: stop passing factory_ref + absence-contract test (factory_ref era ends)",
    "description": "Single carrier for ALL workflow/factory changes (one-PR directive — the fa gate is expensive, no parallel PRs):\n\n1. ai-teammate.yml drops the factory_ref line — the factory resolves the engine from dmtools-agents releases (vars, latest default). Callers swept: dmd #415, agents #931, fa = this PR.\n2. factory_stub_ref_test flips to the absence-contract: NO wrapper passes factory_ref (mirrors dart #415).\n3. Supersedes + closes: #1653 (same drop), #1651 (empty — its gitignore already in main).\n\nAfter this merges, awf's optional no-op factory_ref input (awf#44, transitional) gets removed for good."
  }
}

