      '(required-secret validation rejects inherit)', () {
    for (final entry in explicitSecretStubs.entries) {
      expect(
        entry.value.contains(
          'SOURCE_GITHUB_TOKEN: \${{ secrets.SOURCE_GITHUB_TOKEN }}',
